          />
          <NavItem
            id="navi_notifications"
            label="Notifications"
            style={{ minWidth: "66.5%", maxWidth: "100%", marginLeft: "5.4%", marginTop: 23, alignSelf: "flex-start", minHeight: 38 }}
          />
        </Navbar>
        <Container
          id="box_7"
          layout={{ gap: 0 }}
          geometry
          style={{ paddingBottom: 0, width: "72.6%", flex: "0 0 auto", marginLeft: "4%", marginTop: 14, minHeight: 391 }}
        >
          <Link
            id="lnk_general"
            label="General"
            style={{ minWidth: "22%", maxWidth: "100%", marginLeft: "1%", marginTop: 0, alignSelf: "flex-start", minHeight: 41 }}
          />
          <Field id="inp_display_name" label="Display name" style={{ width: "100%", marginTop: 26 }} />
          <Field
            id="inp_email"
